// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 질문 상세 (23번)" (567e93da9c7c4c88beba5717d9649489).
import "./QuestionDetail.css";
import { useEffect, useRef, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import { getErrorCode, getErrorMessage } from "../api/client";
import { deleteQuestion, getQuestion, readQuestionId, type QuestionDetail as Question } from "../api/question";
import AnswerSection from "../components/answer/AnswerSection";
import AuthorPopover from "../components/AuthorPopover";
import SimilarQuestions from "../components/SimilarQuestions";
import ConfirmModal from "../components/ConfirmModal";
import Header from "../components/Header";
import LikeButton from "../components/LikeButton";
import Markdown from "../components/markdown/Markdown";
import ReportDialog from "../components/report/ReportDialog";
import { tagSearchPath } from "../components/questionList";
import GradeIcon from "../components/GradeIcon";
import ListStatus from "../components/ListStatus";
import StatusBadge from "../components/StatusBadge";
import { buttonClass, CARD, CATEGORY, MENU, PAGE_BACKGROUND, TAG } from "../components/uiStyles";
import { formatDateTime, formatNumber, writerSummary } from "../components/writer";
import { useAuth } from "../hooks/useAuth";
import { useLoginPrompt } from "../hooks/useLoginPrompt";

const LIST_PATH = "/questions";

type LoadState =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean }
  | { status: "done"; question: Question };

// 없는·삭제된 질문은 안내를 보여 준 뒤 목록으로 이동한다 (REQ-QUESTION-005)
const NOT_FOUND_REDIRECT_MS = 3000;

export default function QuestionDetail() {
  const navigate = useNavigate();
  const openLoginPrompt = useLoginPrompt();
  const { user, initializing } = useAuth();
  const [searchParams] = useSearchParams();
  const questionId = readQuestionId(searchParams.get("questionId"));
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [menuOpen, setMenuOpen] = useState(false);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const [reportOpen, setReportOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // 조회할 때마다 조회수가 오르므로 같은 질문은 한 번만 요청한다.
  // (개발 모드 StrictMode는 effect를 두 번 실행해 조회수가 2씩 오르는 것을 막는다. ref는 두 번째 실행에도 유지된다.)
  const requestedId = useRef<number | null>(null);
  useEffect(() => {
    if (questionId === null) {
      setState({ status: "error", message: "없는 질문이에요.", notFound: true });
      return;
    }
    // 새로고침 직후에는 로그인 복구(reissue)가 끝난 뒤 불러온다. 먼저 불러오면 토큰 없이 요청해 liked가 false로 온다.
    if (initializing || requestedId.current === questionId) return;
    requestedId.current = questionId;
    // 유사 질문을 눌러 같은 화면에서 다른 질문으로 바뀌면 열려 있던 메뉴·창을 닫고 맨 위로 올린다.
    setMenuOpen(false);
    setConfirmOpen(false);
    setReportOpen(false);
    window.scrollTo({ top: 0 });
    setState({ status: "loading" });
    getQuestion(questionId)
      .then((question) => {
        if (requestedId.current === questionId) setState({ status: "done", question });
      })
      .catch((error: unknown) => {
        if (requestedId.current !== questionId) return;
        const notFound = getErrorCode(error) === "QUESTION_NOT_FOUND";
        setState({
          status: "error",
          message: notFound ? "삭제됐거나 없는 질문이에요." : getErrorMessage(error),
          notFound,
        });
      });
  }, [questionId, initializing]);

  const notFound = state.status === "error" && state.notFound;
  useEffect(() => {
    if (!notFound) return;
    const timer = setTimeout(() => navigate(LIST_PATH, { replace: true }), NOT_FOUND_REDIRECT_MS);
    return () => clearTimeout(timer);
  }, [notFound, navigate]);

  // 메뉴 바깥을 누르면 닫는다.
  useEffect(() => {
    if (!menuOpen) return;
    function handleClick(event: MouseEvent) {
      if (!menuRef.current?.contains(event.target as Node)) setMenuOpen(false);
    }
    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") setMenuOpen(false);
    }
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [menuOpen]);

  const question = state.status === "done" ? state.question : null;
  // 수정은 작성자만, 삭제는 작성자(채택된 답변이 없을 때)와 관리자 (REQ-QNA-001, REQ-QUESTION-007). 서버에서도 다시 검사한다.
  const isWriter = question !== null && user?.memberId === question.writer.memberId;
  const isAdmin = user?.role === "ROLE_ADMIN";
  const canDelete = isAdmin || (isWriter && !question.accepted);

  function openDeleteConfirm() {
    setMenuOpen(false);
    setDeleteError(null);
    setConfirmOpen(true);
  }

  async function handleDelete() {
    if (question === null) return;
    setDeleting(true);
    try {
      await deleteQuestion(question.questionId);
      navigate(LIST_PATH, { replace: true }); // REQ-QUESTION-007: 삭제 후 질문 목록으로 이동
    } catch (error) {
      // 409 QUESTION_HAS_ACCEPTED_ANSWER 등 서버가 알려준 이유를 모달에 보여 준다.
      setDeleteError(getErrorMessage(error));
      setDeleting(false);
    }
  }

  return (
    <div id="page-question-detail">
      <div className={`${PAGE_BACKGROUND} text-devin-ink font-sans min-h-screen flex flex-col antialiased`}>
        <Header />
        <main className="flex-grow max-w-6xl w-full mx-auto px-4 sm:px-6 py-8 lg:py-10" aria-busy={state.status === "loading"}>
          {state.status === "loading" && (
            <div className={CARD}>
              <ListStatus kind="loading">질문을 불러오는 중이에요.</ListStatus>
            </div>
          )}
          {state.status === "error" && (
            <div className={`${CARD} pb-6 text-center`}>
              <ListStatus kind="error">
                {state.message}
                {state.notFound && <p className="mt-2 text-xs">잠시 후 질문 목록으로 이동해요.</p>}
              </ListStatus>
              <Link className={buttonClass("secondary")} to={LIST_PATH}>
                질문 목록으로 가기
              </Link>
            </div>
          )}
          {question && (
            <>
              <article className={`${CARD} p-4 sm:p-6`} data-purpose="question-detail">
                {/* 상태·카테고리·제목, 작성자·관리자용 더보기 메뉴 */}
                <div className="flex items-start justify-between gap-4 border-b-devin border-devin-ink pb-4">
                  <div className="space-y-2">
                    <div className="flex flex-wrap items-center gap-3">
                      <StatusBadge
                        kind={question.accepted ? "accepted" : question.answerCount === 0 ? "waiting" : "unaccepted"}
                      />
                      <span className={CATEGORY}>{question.category.name}</span>
                    </div>
                    <h1 className="text-2xl font-black text-devin-ink leading-snug break-all">{question.title}</h1>
                  </div>

                  {(isWriter || isAdmin) && (
                    <div className="relative shrink-0" ref={menuRef}>
                      <button
                        aria-expanded={menuOpen}
                        aria-haspopup="menu"
                        aria-label="추가 옵션"
                        className={`${buttonClass("secondary")} w-10 px-0`}
                        type="button"
                        onClick={() => setMenuOpen((open) => !open)}
                      >
                        <span className="material-symbols-outlined text-[20px] leading-none" aria-hidden="true">
                          more_horiz
                        </span>
                      </button>
                      {menuOpen && (
                        <div className={`${MENU.panel} absolute right-0 mt-2 w-28 z-30`} role="menu">
                          {isWriter && (
                            <Link
                              className={MENU.item}
                              role="menuitem"
                              to={`/question-edit?questionId=${question.questionId}`}
                            >
                              <span className={MENU.icon} aria-hidden="true">
                                edit
                              </span>
                              수정
                            </Link>
                          )}
                          {isWriter && canDelete && <div role="separator" className={MENU.divider} />}
                          {canDelete && (
                            <button
                              className={`${MENU.item} ${MENU.danger}`}
                              role="menuitem"
                              type="button"
                              onClick={openDeleteConfirm}
                            >
                              <span className={MENU.icon} aria-hidden="true">
                                delete
                              </span>
                              삭제
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </div>

                {/* 작성자 정보, 작성일·조회수 */}
                <div className="py-4 border-b-devin border-devin-ink flex flex-wrap items-center justify-between gap-y-3 text-sm">
                  <div className="flex flex-wrap items-center gap-2.5">
                    <div className="flex items-center gap-1 font-bold text-devin-ink">
                      <AuthorPopover
                        className="hover:underline"
                        memberId={question.writer.memberId}
                        nickname={question.writer.nickname}
                      />
                      <GradeIcon grade={question.writer.grade} />
                    </div>
                    {writerSummary(question.writer) && (
                      <>
                        <span className="text-devin-gray-light">|</span>
                        <span className="text-devin-gray font-medium text-xs">{writerSummary(question.writer)}</span>
                      </>
                    )}
                  </div>

                  <div className="flex items-center gap-3 text-xs font-semibold text-devin-gray">
                    <time dateTime={question.createdAt}>{formatDateTime(question.createdAt)}</time>
                    <span className="text-devin-gray-light">·</span>
                    <span className="inline-flex items-center gap-1 tabular-nums">
                      <span className="material-symbols-outlined text-[16px] leading-none" aria-hidden="true">
                        visibility
                      </span>
                      조회 {formatNumber(question.viewCount)}
                    </span>
                  </div>
                </div>

                {question.tags.length > 0 && (
                  <div className="py-4 flex flex-wrap items-center gap-2">
                    {/* #61: 태그를 누르면 그 태그로 검색한다 (REQ-SEARCH-003) */}
                    {question.tags.map((tag) => (
                      <Link key={tag} to={tagSearchPath(tag)} className={TAG}>
                        {tag}
                      </Link>
                    ))}
                  </div>
                )}

                {/* 본문 — 마크다운으로 보여 준다 (#62). HTML 태그는 실행하지 않는다 (REQ-QNA-003). */}
                <div className="mt-4 text-sm text-devin-ink leading-relaxed font-normal">
                  <Markdown content={question.content} />
                </div>

                {/* 좋아요·신고 */}
                <div className="mt-6 pt-6 border-t-devin border-devin-ink flex items-center gap-3">
                  <LikeButton
                    key={question.questionId}
                    className={buttonClass("secondary")}
                    isMine={isWriter}
                    likeCount={question.likeCount}
                    liked={question.liked}
                    target="QUESTION"
                    targetId={question.questionId}
                  />
                  {/* 본인 글은 신고할 수 없어 숨긴다 (서버도 400). 비로그인이면 로그인 안내 */}
                  {!isWriter && (
                    <button
                      className={buttonClass("secondary")}
                      type="button"
                      onClick={() => (user ? setReportOpen(true) : openLoginPrompt("신고하려면 로그인이 필요해요."))}
                    >
                      <span className="material-symbols-outlined text-[18px] leading-none" aria-hidden="true">
                        flag
                      </span>
                      신고
                    </button>
                  )}
                </div>
              </article>
              {/* key: 다른 질문으로 바뀌면 펼친 답글·작성 중이던 내용을 새로 시작한다 */}
              <AnswerSection
                key={question.questionId}
                questionId={question.questionId}
                questionWriterId={question.writer.memberId}
                questionAccepted={question.accepted}
                onAccepted={() => setState({ status: "done", question: { ...question, accepted: true } })}
              />
              <SimilarQuestions questionId={question.questionId} />
            </>
          )}
        </main>
        {reportOpen && question && (
          <ReportDialog targetType="QUESTION" targetId={question.questionId} onClose={() => setReportOpen(false)} />
        )}
        {confirmOpen && (
          <ConfirmModal
            tone="danger"
            title="질문을 삭제할까요?"
            message="삭제한 질문은 되돌릴 수 없어요. 답변도 함께 삭제돼요."
            confirmLabel="삭제"
            busy={deleting}
            error={deleteError}
            onCancel={() => setConfirmOpen(false)}
            onConfirm={handleDelete}
          />
        )}
      </div>
    </div>
  );
}
